CREATE TABLE IF NOT EXISTS template_owner(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE);
CREATE TRIGGER IF NOT EXISTS native_company_defaults AFTER INSERT ON company BEGIN
UPDATE company SET primary_color=COALESCE(primary_color,'#25D366'),onboarding_completed=COALESCE(onboarding_completed,0),creditos_saldo=COALESCE((SELECT creditos_trial FROM plan WHERE slug=COALESCE(NEW.selected_plan_slug,'starter')),100) WHERE id=NEW.id;
END;
UPDATE plan SET features='[]' WHERE features='{}' OR features IS NULL;
